insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('838b03f8-0f15-57f5-a5aa-50fe78d4ad09','11-4',11,'일공구잎, 아름다운 한글을 널리 알리다','꽃이 피고 지는 수순 속에서, 잎의 존재는 중요하지 않을 수 없습니다. 타이포그래피 또한 디자인에 있어 가장 기틀이 되는 요소이기도 합니다. 잎은 소모임 ‘꽃’의 브랜드로, 식물의 기본적인 생명 활동 기관인 ‘잎’에 빗대어 가장 기틀이 되는 타이포그래피를 주축으로 이야기를 전개해 나갑니다. 잎의 첫 이야기, ‘일공구잎’은 한글날을 기념하여 한글을 분석하고 연구함으로써 보다 실험적이고 다채로운 작업물을 선보입니다. 그로써 한글의 가능성을 두드러지게 나타내는 것은 물론, 한글의 조형성과 아름다움을 알리는 데 목표합니다.','2024.04.02. - 2024.04.30.','워크샵',3,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('2f20b622-fe47-5ad0-a94c-bdbcc7cfd7d9','838b03f8-0f15-57f5-a5aa-50fe78d4ad09','','',0,true) on conflict(id) do nothing;
