insert into public.works(id,project_id,title,description,sort_order,published) values('d9b33c4f-95de-51da-a4ad-ea1032064b25','db6c79ca-becd-59e8-a567-03143bcc2c61','','한 획마다 꽃잎의 부드러움이 흐르듯,흘려 써지는 필기체에 꽃의 곡선을 담아봤습니다. 작가의 개성이 담기는 필기체처럼, 꽃 각각의 아름다움이 자연스럽게 담기는 것을 표현하고자 했습니다.',6,true) on conflict(id) do nothing;
