insert into public.works(id,project_id,title,description,sort_order,published) values('70f9b1ad-4cc0-52b3-a316-b6659965e9f4','db6c79ca-becd-59e8-a567-03143bcc2c61','','‘꽃’이라는 글자의 구성요소들을 하트의 형상처럼 시각화했습니다. 이를 통해 꽃을 보며 사랑에 빠질 것 같은 봄날의 들뜬 분위기를 글자 속에 녹여내었습니다.',8,true) on conflict(id) do nothing;
