insert into public.works(id,project_id,title,description,sort_order,published) values('e75e6982-d3cc-5127-a3a7-2298780a9656','db6c79ca-becd-59e8-a567-03143bcc2c61','','꽃은 여린 물성을 갖고 있음과 동시에 위를 향해 꼿꼿이 뻗어있는 단단한 생명체입니다. 꽃이 갖고 있는 모순적인 두 가지 성질을 표현하기 위해 간결한 곡선과 직선의 조화로 디자인한 레터링입니다.',10,true) on conflict(id) do nothing;
