insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('a3acc45c-faf5-541c-a1c0-7b84b37ea88d','12-missing-3',12,'스터디','활자 제작 도구인 글립스와 꽃의 작업을 아카이브하기 위한 웹 스터디를 진행했습니다. 기존 활동을 아카이브하는 웹사이트를 구축하고, 한글이 아닌 라틴과 딩벳 활자체를 제작하며 색다른 타이포그래피 실험을 시도했습니다.','2024.05.25. - 2025.03.10','서체, 워크샵',2,true) on conflict(id) do nothing;
