insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('01b26860-d8f7-52e0-a8d2-013eddc8818f','12-3',12,'한글 악보집','578번째 한글날을 기념하여 한글의 아름다움과 가치를 담아 <한글 악보집>을 제작하였습니다. 한글의 역사를 되짚어보며 글자의 구조적, 조형적 특성을 담아 총 14개의 동요로 구성한 악보집입니다. 우리에게 친근한 음악과 타이포그래피의 요소를 결합하며, 보다 많은 사람들에게 한글날의 의미가 가깝게 다가가기를 바랍니다. 어린 시절 불렀던 익숙한 멜로디를 떠올리며, 한글 가사의 흐름을 따라 감상해보세요.','2024.09.03. - 2024.10.01.','레터링, 책',3,true) on conflict(id) do nothing;
