insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('3d9cc219-976d-5bac-a012-aafa55c13724','12-4',12,'기념일 엽서','13가지의 기념일을 축하하는 엽서입니다. 특별한 날, 더 가깝게 다가오는 삶의 가치들을 꽃과 함께 종이 한 장에 눌러 담아 보관합니다.','2025.01.07. - 2025.02.11.','레터링',4,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('10ef1409-f0ff-5f83-a594-89dbb3dc7d05','3d9cc219-976d-5bac-a012-aafa55c13724','작업 이름','작업 설명',0,true) on conflict(id) do nothing;
insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('35815134-d02d-5cb3-a06e-d7d77b4af5c8','12-5',12,'사물 활자체','사물에서 모티브를 얻어, 그 특성을 담아낸 레터링과 서체를 제작했습니다. 같은 대상에서 도출된 두 결과물을 비교하며 사물을 바라보는 새로운 시각을 만나보세요.','2024.07.16. - 2025.03.04.','레터링, 서체, 책',5,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('6fc5fd51-2b26-5ddd-afd7-bd1db6f1f270','35815134-d02d-5cb3-a06e-d7d77b4af5c8','본연[뼈]','부리 글꼴 ‘본연’은 인체의 뼈대가 지닌 견고함과 유기적 연결성을 모티브로 한 본문용 서체입니다. 뼈’Bone‘과 연결의 ’연‘을 결합해 탄생한 이름으로 견고하면서도 자연스러운 흐름을 담고자 했습니다. 글자의 각진 끝처리는 뼈와 뼈가 만나는 관절 부위를 연상시키며 이는 글자와 글자 사이의 유기적인 연결을 상징합니다. 본문 텍스트에서도 안정감 있는 가독성과 함께 독특한 개성을 전달하고자 했습니다.',0,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('1ca23908-d16a-5c9a-a9b3-9fba64ac8db8','6fc5fd51-2b26-5ddd-afd7-bd1db6f1f270','google_drive','1AElt8HE-dMfd253yocFUi1NQQQXrMLKg','본연[뼈]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('093e1a38-873f-52a5-ae5c-174a839c88b3','35815134-d02d-5cb3-a06e-d7d77b4af5c8','불피움[불]','불피움체는 불의 강렬한 에너지와 생명력을 담아낸 서체입니다. 불이 지닌 역동적이고 예측 불가능한 모양새, 강렬한 온도와 빛의 대비, 그리고 불길 속에서 다시 태어나는 재생의 의미를 반영하여 디자인하였습니다.각 글자에서 보이는 미세한 흔들림과 불꽃과 같은 곡선을 통해, 글자가 마치 타오르며 살아 숨 쉬는 듯한 느낌을 주어 독자에게 시각적 열기를 전달하고자 했습니다.',1,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('8bd67998-e3ca-5fa8-a198-0f0da3a01eac','093e1a38-873f-52a5-ae5c-174a839c88b3','google_drive','1RlSVvMW8RXYe94C2AjjxtuGJhYQB4Cnd','불피움[불]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('38e52277-cbdf-5f3d-a3ee-5aee289d572f','35815134-d02d-5cb3-a06e-d7d77b4af5c8','토마토체[토마토]','토마토체는 토마토를 모티브로 활용하여, 울퉁불퉁한 토마토의 표면과 토마토를 자른 단면이 서로 겹치는 부피감을 담은 서체입니다.',2,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('82ee0ecf-649a-50c6-ab64-05902278e662','38e52277-cbdf-5f3d-a3ee-5aee289d572f','google_drive','18aLW_bWfHyCYxgTpw7-PEEREAHQTYr7s','토마토체[토마토]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('aa3b5db1-efe9-5c5c-a343-87aed74dbf75','35815134-d02d-5cb3-a06e-d7d77b4af5c8','빵 지키미[빵 클립]','빵을 맛있게 지켜주는 빵 클립을 모티브로 한 한글 서체입니다. 작고 하찮은 존재로 소중히 대접받지 못하고 이리저리 나뒹굴지만, 사실 우리의 소중한 빵의 맛을 지켜주는 고마운 존재입니다. 빵 클립의 작고 섬세한 각들이 담긴 서체로 귀엽고 따뜻한 인상을 갖습니다.',3,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('cd0ffe28-599c-51ff-a50b-a196e0a596e1','aa3b5db1-efe9-5c5c-a343-87aed74dbf75','google_drive','1BzwthkDgvYR7Iz0tlOmpOb7QQZnpeh2f','빵 지키미[빵 클립]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('d46a712d-6ab8-55e6-ab33-1774b045d89a','35815134-d02d-5cb3-a06e-d7d77b4af5c8','구김살[비닐]','비닐에 생기는 구깃한 주름을 사람의 어두운 성격을 표현하는 단어인 ‘구김살''에 비유해 볼드하고 강한 인상의 글자로 디자인 했습니다.',4,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('797077e6-2059-50f5-aff4-7b04159c52ba','d46a712d-6ab8-55e6-ab33-1774b045d89a','google_drive','1cJ2OuwNOeqivGk594uHfLBqn5Yj35C8b','구김살[비닐]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('f68f16e0-f29d-57ae-a153-3a17b5199d99','35815134-d02d-5cb3-a06e-d7d77b4af5c8','마리[실마리]','실타래 속 실마리에서 착안하여 디자인한 마리체입니다. 실의 이어지고 휘는 성질이 라틴의 이텔릭과 닮았다고 생각했습니다. 라틴과 닮은 자모에서 한글을 잘 모르는 사람들이 고개를 기웃거렸으면, 하는 장난기에서 만들어진 서체입니다.',5,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('1dc09709-cfab-5cdb-a2f4-16562c0cead2','f68f16e0-f29d-57ae-a153-3a17b5199d99','google_drive','1x9VzbZYxC5e3dYBD9MkMKYzDBltfXejU','마리[실마리]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('d2f52004-592d-5435-a6fb-2ec0377fb3d2','35815134-d02d-5cb3-a06e-d7d77b4af5c8','징크스[물감]','입시때 썼던 튜브 물감을 보면서 시험에 대한 징크스를 생각하게 되었습니다.물감을 짜면 구겨지는 알류미늄 튜브 물감의 뾰족한 부분,물감 뚜껑의 쉐입, 흘러내린 물감의 느낌 등을 모티브삼아 디자인하였습니다. 글자를 직사각형안에 가득 채워 ⟨징크스에 갇혀 있다⟩ 라는 느낌을 주려고 했습니다.',6,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('c201c820-ee83-5cf0-aeb0-f2d8859573f1','d2f52004-592d-5435-a6fb-2ec0377fb3d2','google_drive','1PVV2ZPXv0RzxWjomA82zexsrVX5dqSHW','징크스[물감]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('17bae53f-8ffd-5338-a97b-97ad4f7d3ac6','35815134-d02d-5cb3-a06e-d7d77b4af5c8','스케일[줄자]','스케일은 줄자의 특성을 모티브로 한 제목용 서체입니다. 정확한 길이를 재는 도구라는 점을 바탕으로 기하학적인 인상을 전달하고자 했습니다. 줄자의 길고 얇게 늘어지는 특성을 반영해 얇은 두께의 장체의 비율로 설정하고, 줄자가 둥글게 구부러지는 독특한 형태를 담아 디자인 했습니다.',7,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('59d1f688-9a32-5505-a304-b3cd8e07e4ae','17bae53f-8ffd-5338-a97b-97ad4f7d3ac6','google_drive','1Xsisc2t26qNR88aAe__JQrEaEKgCKbhR','스케일[줄자]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('fc1802f8-2f03-50c6-a730-454b24471610','35815134-d02d-5cb3-a06e-d7d77b4af5c8','컵 속 부표[티백] ','컵 속을 조용히 유영하며 물을 차로 바꾸는 티백을 모티브로 한 한글 서체입니다. 티백과 부표는 각자의 목적을 가지고 물 위에 떠있는 모습이 닮았습니다. 또, 티백은 무색무취의 물을 차로 바꾸며 분위기를 전환한다는 점이 부표(목표, 표적의 의미)가 넓은 바다(인생)의 분위기를 바꾸는 점과 유사합니다. 이렇게 물 속을 떠다니는 분위기 메이커, 티백이 머그컵 속에 떠있는 모습을 모티브 삼아 동그란 틀 안에 글자를 넣어 작업해 보았습니다.',8,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('084e0fab-f935-53e1-ac33-e30b4762fb2d','fc1802f8-2f03-50c6-a730-454b24471610','google_drive','1YLbD-htqFtWwhWkVXS0HDSuTP7cX7ZWE','컵 속 부표[티백] ',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('3fac2f8c-4245-5245-aa75-1ec41f894491','35815134-d02d-5cb3-a06e-d7d77b4af5c8','종이[색종이]','색종이로 자르고 붙이는 과정에서 남은 삼각형, 사각형 같은 작은 조각들을 모아내는 데서 착안한 작업입니다. 버려질 뻔한 조각들을 하나로 모아 밝고 발랄한 이미지로 재구성하고자 했습니다. 각 요소가 조화롭게 어우러져 따뜻하면서도 힘 있는 메시지를 전할 수 있도록 디자인했습니다.',9,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('3a8e1586-a1d8-5dc5-a754-71847563421a','3fac2f8c-4245-5245-aa75-1ec41f894491','google_drive','1-hdCJhwybAYi61oPBJCL6QHsUc63MK8W','종이[색종이]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('2fc70563-a626-583c-a0dd-b275758592f7','35815134-d02d-5cb3-a06e-d7d77b4af5c8','마음획체[마스킹테이프]','우리 일상에서 다양한 도움을 주는 마스킹테이프의 다정함을 담아 디자인된 서체 ‘마음획체‘입니다.',10,true) on conflict(id) do nothing;
