insert into public.works(id,project_id,title,description,sort_order,published) values('ab5c6bbc-76c9-5fc1-a347-e94ba81099ca','35815134-d02d-5cb3-a06e-d7d77b4af5c8','찝[실핀]','실핀의 곧음, 구불구불함, 둥근 맺음을 담아낸 한글서체입니다.',11,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('93009f38-1cca-5c26-a7c7-7e2a187a4371','ab5c6bbc-76c9-5fc1-a347-e94ba81099ca','google_drive','1T5Rmy1y6eaMj0aw_xMVSUQx6BIe46DUF','찝[실핀]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('8e9c01d2-bebd-5fd1-aeed-12c08d7a05de','35815134-d02d-5cb3-a06e-d7d77b4af5c8','파티[컨페티]','축제의 즐거움과 다채로운 매력을 글자에 담아낸 서체입니다. 여러개의 종이 조각으로 이루어진 컨페티의 특성을 반영해 정사각형 비율을 기본으로 한 모듈형 서체를 구성했습니다. 다양한 도형 장식을 더해 흩날리는 컨페티의 생동감과 화려함을 떠올릴 수 있도록 작업했습니다.',12,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('58d3331d-ca73-5eef-a59e-45814ddec55d','8e9c01d2-bebd-5fd1-aeed-12c08d7a05de','google_drive','19h2fh686j1GGZweUKo9SeanimNtMs5vQ','파티[컨페티]',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('6fd2a1df-59c1-5216-af90-c005d636de32','35815134-d02d-5cb3-a06e-d7d77b4af5c8','탄성에너지[용수철]','탄성에너지체는 용수철의 반복적인 나선 형태와 가변적인 높낮이를 모티브로 제작한 탈네모꼴 서체입니다. 힘든 때에도, 우리 안에는 용수철처럼 다시 일어설 힘이 있다는 것을 잊지 않길 바라며!',13,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('301d39a8-3dee-51cf-a645-54b9408c91b3','6fd2a1df-59c1-5216-af90-c005d636de32','google_drive','1WRxq1hY_2dti9Y8lZ7bw-B15qO3Iv_H-','탄성에너지[용수철]',0) on conflict(id) do nothing;
insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','13-1',13,'꽃 한 글자 레터링','‘꽃’은 하나의 글자이면서도, 그 자체로 완결된 하나의 단어입니다. 이 견고한 한 글자는 얼마나 다채로운 인상을 가질 수 있을까요? ‘꽃 한 글자’로 시작된 꽃 13기의 지난 1년간의 과정을 따라가며, 글자가 만들어내는 다양한 얼굴을 만나보세요.','2025.04.08. - 2025.04.22.','레터링',0,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('e04b3777-054e-5f69-a39b-4349c5b2e098','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','외적인 아름다움보다 거친 환경 속에서도 꺾이지 않고 피어나는 강인한 꽃의 생명력과 단단함에 주목했다. 흔히 유려한 곡선으로 형상화되는 꽃의 이미지를 직선과 각진 형태로 재해석했다.',0,true) on conflict(id) do nothing;
