insert into public.works(id,project_id,title,description,sort_order,published) values('ffcdd12f-227b-53fc-a982-3f83fcc4acac','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','‘꽃’ 한 글자를 한 획으로 이어서 그렸다.',1,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('7cf3c201-dd8a-54be-a3fe-ee1853e4f46c','ffcdd12f-227b-53fc-a982-3f83fcc4acac','google_drive','1rQYGIuqLZhJ_plmYDCpIXuex55Q6PWYv','김소현',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('05c32823-f8c0-52c8-abcd-1857030c8144','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','먼저, 원 5개로 이루어진 꽃 형태의 도형을 틀로 삼았다. 그 위에 한글 흘림체에서 착안하여, 최소한의 획으로 ‘꽃''이라는 글자의 부드러운 흐름을 표현하고자 했다.',2,true) on conflict(id) do nothing;
