insert into public.works(id,project_id,title,description,sort_order,published) values('10b9c0e4-a706-580d-a8a2-fc95f085f153','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','하늘하늘한 꽃이 피어오르기 전 꽃 봉오리의 무게감 있는 곡선의 인상을 담아낸 데칼코마니 레터링이다.',3,true) on conflict(id) do nothing;
