insert into public.works(id,project_id,title,description,sort_order,published) values('9a9eb0f9-c688-58f0-a9d8-25d942dcee38','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','‘웃음-꽃’은 꽃이 피어나듯 환하고 즐겁게 웃는 웃음을 비유적으로 이르는 말이다. 기호 ‘^(caret)’이 ‘^^’와 같이 웃음 이모티콘으로 사용되는 것에 착안해 웃음꽃을 표현했다.',4,true) on conflict(id) do nothing;
