insert into public.works(id,project_id,title,description,sort_order,published) values('57a1400e-2f9a-5254-a150-f94ca260d226','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','손글씨를 바탕으로, 마치 누군가에게 전하는 편지같은 감성을 표현했다. 획 하나하나에 조심스럽고 진심 어린 마음을 담아, 보고 있으면 왠지 누군가 나를 생각하며 써준 글씨같길 바랐다. 일기, 편지, 혹은 고백의 순간처럼 작지만 진심이 필요한 순간에 어울리는 글자이다.',5,true) on conflict(id) do nothing;
