insert into public.works(id,project_id,title,description,sort_order,published) values('8e7898e1-3576-5c32-a182-6285aaf3ad44','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','거친 태풍 속 ‘꽃'' 을 컨셉으로 잡았다. 장미의 가시를 모티브 삼아 모서리 포인트를 사용했고 꽃의 부드러움과 태풍의 강함을 대조적으로 드러나도록 작업했다.',6,true) on conflict(id) do nothing;
