insert into public.works(id,project_id,title,description,sort_order,published) values('111cc567-4749-5f80-aef1-86704634be20','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','붓으로 쓴 듯한 필압의 변화가 특징이며, 글자의 흐름과 리듬감을 강조하여 생동감 있는 형태로 디자인했다. 각 획은 유기적으로 연결되어 꽃이 피어나는 듯한 이미지를 시각적으로 전달하고자 했다.',7,true) on conflict(id) do nothing;
