insert into public.works(id,project_id,title,description,sort_order,published) values('50257707-c987-5b73-aca8-2ae51d5a8a76','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','다섯개의 꽃잎을 가진 꽃처럼 그려내고자 했다. 유연하고 우아한 인상이 느껴지도록 곡선과 꼬임의 형태를 강조하여 표현했다.',8,true) on conflict(id) do nothing;
