insert into public.works(id,project_id,title,description,sort_order,published) values('34929b5c-2a61-59c1-af57-ff72df706fbc','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','붓글씨에서 모티브를 얻은 레터링 작업이다.가늘고 두꺼운 획의 조화를 통해 글자에 리듬감과 흐름을 주었고, 얇은 선으로는 붓 특유의 여운을 표현하고자 했다.',9,true) on conflict(id) do nothing;
