insert into public.works(id,project_id,title,description,sort_order,published) values('050e61ee-bdb8-5537-a37e-18c88a950047','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','손글씨를 기반으로 획굵기 차이를 주어 표현했다. 산뜻하고 가벼운 느낌을 주는 꽃이다.',10,true) on conflict(id) do nothing;
