insert into public.works(id,project_id,title,description,sort_order,published) values('13e0894d-9de6-55de-a01c-15746220e284','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','얇고 균일한 획을 통해 길게 뻗은 꽃을 표현하고자 했다. 단순하고 곡선적인 이미지는 바람에 가볍게 흔들리는 듯한 꽃의 형상을 보여준다.',11,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('6b27fd92-8b55-59da-acd8-6706b9c7c513','13e0894d-9de6-55de-a01c-15746220e284','google_drive','1vfsnKlPlutNhyzkz8fO9jEghIhipEjam','최서원',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('9c13fc57-7d64-52f3-a982-420812413f1e','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','수많은 작은 꽃이 모여 원기둥을 이루는 히아신스의 꽃송이를 떠올리며 그렸다. 강한 획 대비와 둥근 형태가 특징이다.',12,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('4165a3a0-5832-5dc5-ae6c-bdccff3b5730','9c13fc57-7d64-52f3-a982-420812413f1e','google_drive','1kW800PWxQY35-GTBWGHOpbgAIfHUjfPK','최정안',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('44af6035-8f74-5f2d-a9ab-c0639068fdea','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','장미의 형태에서 모티브를 얻어 ‘꽃''을 그려냈다. 부드럽게 흐르는 곡선에는 꽃잎의 부드러움을, 날카롭게 꺾이는 직선에는 장미 가시의 긴장감을 담고자 했다. 서로 다른 선들이 어우러져, 장미가 지닌 아름다움과 강인함을 동시에 드러낸다.',13,true) on conflict(id) do nothing;
