insert into public.works(id,project_id,title,description,sort_order,published) values('931bd205-4ba2-528c-af88-bf96286833d7','efdd6cf5-2558-565f-a5fa-15b2a7c16fc2','','은방울꽃 줄기에서 느껴지는 자연스러운 곡선을 담은 레터링이다. 무심하지만 단단하게 떨어지는 획이 특징이다.',14,true) on conflict(id) do nothing;
