insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('b3a68a5e-fecf-5d78-ac80-c2beed139b0c','13-2',13,'밈 레터링','밈(meme)은 디지털 환경에서 반복적으로 공유되고 확산되는 동시대의 언어입니다. 이미지와 텍스트 속 말투와 리듬은 하나의 맥락이 되고, 패러디와 변형을 거치며 새로운 의미를 만들어냅니다. 이러한 감각을 한글 타이포그래피의 형식으로 다시 옮겨, 형태만으로 의미와 유머를 전합니다. 다시 기록된 지금 시대의 언어를 만나보세요.','2025.05.13. - 2025.06.17.','레터링',1,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('78eec0c7-92d2-5455-a837-9996a9e24e60','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','제발이라는 감정','‘제발’이라는 말이 단순한 간청을 넘어, 설명 불가능한 절박함을 뜻하는 하나의 감정처럼 느껴진다. 이러한 상태를 과장해 표현한 밈이다.',0,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('98d833e2-a258-519b-acce-73de99e50752','78eec0c7-92d2-5455-a837-9996a9e24e60','google_drive','18mvwizU8DywOUgeddGPM2qzQJ23FPq_I','제발이라는 감정',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('b9c80e0c-2dce-5a94-aaf9-87ae29c7adc8','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','사실 넘 부러웠어요','다른 사람이 가진 좋은 것을 부정하며 깎아내리다가 사실은 부러운 마음에 그랬다는 것을 결국 인정한다. 못난 태도에서 수줍은 태도로 바뀌는 것이 귀여운 밈이다.',1,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('4cd946cf-5f5d-5ed1-a8f5-a2e68e4fa2c1','b9c80e0c-2dce-5a94-aaf9-87ae29c7adc8','google_drive','1YXF5rZJm6etE_Dq-UlyAe8E6nkiJ2Iro','사실 넘 부러웠어요',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('c33cb3ef-5bb7-52cf-a810-3101ed29e27f','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','테마를 Love(으)로 변경하였습니다','인스타그램 시스템 공지문 형식을 패러디한 밈으로, 무감정한 안내 문장 속에 설렘이라는 감정이 담긴 형식과 내용의 대비에서 웃음을 만든다. 감추고 싶었던 진심이 드러나는 순간이 제 3자까지 민망하게 하는 점 또한 포인트라고 할 수 있다. 조사 괄호 표기 방식까지 활용해 한국 인터넷 특유의 감성을 드러낸다.',2,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('595f1487-e9ae-5c0d-a05c-434fec2fa1f3','c33cb3ef-5bb7-52cf-a810-3101ed29e27f','google_drive','1pSd1DQEHjeQ3KduW6s7KmVOCid2wVMY9','테마를 Love(으)로 변경하였습니다',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('fb0923c2-aaad-5da9-afd3-28df9cce5ad8','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','지금 지쳤나요? 아니요','무한도전 422화에서 늦은 밤 촬영 중 오간 질문과 답변이다. 지쳐 보이는 상황에서도 “아니요”라고 말하는 장면은 실제 속마음과 다른 태도를 드러내며, 현대인들이 감정을 숨기고 버티는 순간에 대한 공감을 불러일으킨다.',3,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('06be97cd-da43-5e56-aad1-8507eec2ef9b','fb0923c2-aaad-5da9-afd3-28df9cce5ad8','google_drive','1C5FpM4w8qTfKTCAMUa0o7FXz58su_6XW','지금 지쳤나요? 아니요',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('68d748be-c400-55ce-abb8-a76d3c026017','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','네잎클로버를 찾았다! 좋은 일이 생기려나?','닌텐도의 비디오 게임 《동물의 숲》은 동물 주민들과의 따뜻한 교류와 소소한 일상을 중심에 둔 생활형 게임이다. 이 밈은 게임 속에서 유래해 퍼진 대사로, 네잎클로버를 발견한 순간의 반가움을 통해 큰 보상 없이도 하루를 충분히 특별하게 느끼는 마음을 전한다.',4,true) on conflict(id) do nothing;
