insert into public.works(id,project_id,title,description,sort_order,published) values('85e16de7-d27f-5e4f-a4d5-9003f5304b7f','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','고진감래 - 고용해주셔서 진짜 감사한다 집에 갈래','사자성어 ‘고진감래’를 현대 직장 현실에 빗대 비튼 표현으로, 어렵게 취업했지만 과도한 업무에 지쳐 감사와 탈주 욕망이 동시에 드러나는 직장인 자조 밈이다.',5,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('f83fdad4-b4b7-5755-a7af-b65517cf655b','85e16de7-d27f-5e4f-a4d5-9003f5304b7f','google_drive','1olrWdfVQUOy3tGmXauSXHkgdioAKmuGI','고진감래 - 고용해주셔서 진짜 감사한다 집에 갈래',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('14f1e1cf-5440-53cb-a784-efcc2952e393','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','상담 무료 편 들어드립니다','인억울한 일도 많고 힘든일도 많았을 하루에 조언을 하기보다는 아이처럼 순수하게 이 세상에서 무조건적인 편을 들어줄 수 있다는 의지를 담아 표현하였다',6,true) on conflict(id) do nothing;
