insert into public.works(id,project_id,title,description,sort_order,published) values('2daba3f5-6c82-5cf6-a99c-1e1d95ecef63','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','나의 인생처럼 천천히','아이돌 그룹 엔시티 위시의 멤버가 한 말로, 느리지만 천천히 목적지에 도달하기 바라는 사람들의 공감을 얻으면서 유명해졌다.',7,true) on conflict(id) do nothing;
