insert into public.works(id,project_id,title,description,sort_order,published) values('158fe65e-22c3-5f3a-a685-ff10dddf775b','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','손가락으로 복숭아 누르지 마세요 (초인종이 아닙니다)','과일가게 아저씨의 간절함이 담긴,아직 팔리지 않은 복숭아들을 보존하기 위한 문구이다.어느 과일 가게에서 A4용지에 이 문구를 프린트해 복숭아 앞에 둔 모습을 누군가 SNS에 공유하며 밈화되었다.현재는 볼이 말랑한 덕질 대상을 지칭하는 등 애정 어린 표현으로 의미가 확장되어 사용되고 있다.',8,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('44ffcd11-3201-53de-a44f-19fdc465011a','158fe65e-22c3-5f3a-a685-ff10dddf775b','google_drive','1E4UwNINW5JJa34qJmWmjgg1eUVWevVpO','손가락으로 복숭아 누르지 마세요 (초인종이 아닙니다)',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('9a72ffca-68c3-5203-a557-28160fe7e871','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','찾았다 내 도파민','쾌락과 보상을 느낄 때 분비되는 신경전달물질인 도파민에서 비롯된 밈이다. 자극적이거나 취향을 정확히 저격하는 콘텐츠를 발견했을 때, 순간적으로 느끼는 강한 재미와 만족감을 표현한다. 일상에서 짜릿한 흥미를 마주했을 때 쓰인다.',9,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('567b2a81-f9a6-5a50-aa6b-e8c3b0bc4d28','9a72ffca-68c3-5203-a557-28160fe7e871','google_drive','1FGR58tC7X26tbt9twAnCeOlJ3QySZGN0','찾았다 내 도파민',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('ad6a6dd6-f9c7-5393-a8ff-a444fbe7a9c5','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','리얼 허거덩거덩스한 상황','‘헉’을 과장해서 만든 ‘허거덩’을 변형시킨 표현이다. 문구와 팔짱 낀 중년남성의 묘한 표정이 결합된 이미지가 웃음 포인트다.',10,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('6cd8381e-12a9-5f37-a8d6-d24e54235bec','ad6a6dd6-f9c7-5393-a8ff-a444fbe7a9c5','google_drive','1MVGLHMKg0kD2MGnIyJ0Fum_k8RjPg5L-','리얼 허거덩거덩스한 상황',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('abf26bac-4e15-55b9-a490-1fcc066a5c72','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','오늘 기분이 어떠신가요?','오늘 기분이 어떠냐는 질문과 그에 대한 선지 세 개를 과장된 이미지로 표현했다. ‘신남’ 선지의 표정도 딱히 신나 보이지 않는 것이 재미있다. ',11,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('dc960c3f-2edc-5155-ab89-c732ab319392','abf26bac-4e15-55b9-a490-1fcc066a5c72','google_drive','1jeVcTjCRkCpYLaiQRgF7Ab9tqhLxT1JA','오늘 기분이 어떠신가요?',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('012a777d-8ad2-517b-a177-2374df0caeba','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','요즘은 다들 이렇게 입어요','그림 속 인물의 차림과 유사한 패션 아이템을 한꺼번에 착용한 인물을 놀리거나 풍자하는 맥락에서 사용된다. 통이 넓은 바지, 화려한 후드티, 스냅백과 볼드한 목걸이를 찬 차림을 두고 이 짤의 주인공같다고 표현하며 ‘요즘’ 세대의 힙합 스타일을 대표하는 이미지가 되었다.',12,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('913a4dbe-f299-5b88-a1f8-37e202cb81d1','012a777d-8ad2-517b-a177-2374df0caeba','google_drive','1wwvE66SH6NJG2R19Hh2IDX1JblFvQsiy','요즘은 다들 이렇게 입어요',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('f83d203e-e695-5ded-aeb5-4f5d234d97b5','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','아유... 하기 싫어...','이 밈은 MBC 예능프로그램 <무한도전>의 한 장면이다.박 차장 역의 박명수가 책상 앞에서 지친 표정으로 “아유… 하기 싫어…”라고 말하는 순간이다. 해야 할 일은 쌓였지만 의욕은 바닥인 심리를 솔직하게 보여줘서, 직장인이나 학생들에게 공감용으로 자주 쓰인다.',13,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('9fe67af1-112a-57d4-ad06-8a08ab30c564','f83d203e-e695-5ded-aeb5-4f5d234d97b5','google_drive','1tl4gF-dzMlQuyokXs3mYv0RG98yvMqfg','아유... 하기 싫어...',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('131fed6b-946d-5411-ad33-566e01c7b073','b3a68a5e-fecf-5d78-ac80-c2beed139b0c','네가 가야한 곳에만 집중해야 해 다른 달팽이들은 신경쓰지 말고','2018년 영국 노퍽주에서 열린 달팽이 경주의 한 참가자가 자신의 달팽이를 응원하는 인터뷰 장면이다. 달팽이에게 진지하게 조언의 말을 건네는 다소 엉뚱한 이 모습은 경쟁과 비교에 지친 많은 이들에게 뜻밖의 위로를 주었다.',14,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('5bd33793-612e-5c37-a531-a89676f2fdeb','131fed6b-946d-5411-ad33-566e01c7b073','google_drive','1o2DmvQ5RInSym61AoeVbv3DkaZoMpiah','네가 가야한 곳에만 집중해야 해 다른 달팽이들은 신경쓰지 말고',0) on conflict(id) do nothing;
insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('c8ed53b0-c0aa-57fd-aa64-2b7e76bdbc0a','13-3',13,'한글로 쓰기','로마자의 표현 양식이 한글의 조합 구조에 반영된다면 어떤 모습일까요? 라틴 서체의 특징을 한글의 구조 안에서 새롭게 해석해 보았습니다. 문자 체계 사이에서 이루어진 선택과 변형의 과정을 상상하며 한글 레터링을 감상해 보세요.','2025.05.13. - 2025.06.17.','레터링',2,true) on conflict(id) do nothing;
