insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('3edc4b4f-5ef7-5396-aa64-2a8abba8e861','13-4',13,'영화에서 글자로','각자가 고른 한 편의 영화에서 출발해 한 벌의 서체를 제작했습니다. 우리에게 다가온 한순간의 장면이나 대사를 모티브로 삼아, 그 순간에 어울리는 글자를 상상해 보았습니다. 서체를 소개하는 글꼴 보기집을 감상하며, 영상 매체가 글자들의 호흡으로 전환되는 감각을 느껴보세요.','2025.11.04. - 2026.01.27.','서체, 책',3,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('bef0d0d9-d0bf-5615-ac12-8cdb298dd716','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','우희','‘우희는 민부리 계열의 본문용 서체로 잔잔한 획 대비를 통해 영화 《패왕별희》의 긴장과 서정을 담는다. 전통 속에서 운명을 담담히 노래하는 인물의 감정을 시대성과 함께 서사적으로 드러낸다.',0,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('93b8c765-620a-5148-a549-8df61e857d7f','bef0d0d9-d0bf-5615-ac12-8cdb298dd716','google_drive','1uiQIRHtd9HhXlHSLj9zK6xje5J3PvncU','우희',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('1481f66d-5508-5a98-a932-75c0da540350','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','철심체','영화 브루탈리스트를 소재로 그린 글자들이다. 브루탈리스트는 브루탈리즘 건축을 소재로한 영화이다. 폭이 좁고 단단한 구조가 두드러지는 글자들을 그렸다.',1,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('9ebf2b7b-c175-5ee5-ac16-119575d736c9','1481f66d-5508-5a98-a932-75c0da540350','google_drive','1PQp7XV50z7ojX7gpWCfbG_zwtwDx-i-8','철심체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('4ffd329c-02f8-5fb7-a450-4a83d47a2c32','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','잉걸물체','픽사의 애니메이션 〈엘리멘탈〉에 등장하는 여러 원소의 형태적 특징에서 착안한 레터링과 글꼴을 소개하는 글꼴보기집이다. 크게 4개의 파트로 이루어져 있으며, 각 파트의 케이스는 4원소의 화합을 나타내는 퍼즐로 기능하기도 한다.',2,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('4be9c013-7cf4-503c-a6c5-30db63ed971b','4ffd329c-02f8-5fb7-a450-4a83d47a2c32','google_drive','17S46KySQhcCwPJqUHHLPPP1y1Ngps-cn','잉걸물체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('7d9238e4-4152-592c-a8ea-ec0edcfebf7e','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','베이브체','영화 <베이비 드라이버>를 모티브로 제작한 서체 ‘베이브’를 소개하는 책이다. 질주 장면이 주는 속도감과 강렬한 인상을 페이지 디자인과 제본에 담았으며, 주인공의 주요 소지품 카세트 테이프를 책의 구조와 형식에 반영했다.',3,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('53c157d1-4fae-5db3-a67d-9e8027d71e5c','7d9238e4-4152-592c-a8ea-ec0edcfebf7e','google_drive','1FFoHa9PLUwjMSOdGRupD0sV69EhJb2aB','베이브체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('9a02c237-d9f5-55b0-ae7f-57847b7e1922','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','달림체','영화 〈시간을 달리는 소녀〉를 모티브로, ‘누군가 달려가고 있다’는 잔상을 남기는 레터링과 그 인상을 확장한 서체 〈달림체〉를 디자인했다. 가로로 긴 페이지를 곱씹듯 읽으며, 눈으로 달려보길 바란다.',4,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('fb900c1c-6d9a-59ec-a930-4e2cc0a1bb7f','9a02c237-d9f5-55b0-ae7f-57847b7e1922','google_drive','1Mp8XsZn43BYgKA-PxsiTriL_kMozcALa','달림체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('b334dae2-42e8-5f86-a27d-32291c401bec','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','연인체','사‘연인’ 서체는 디자이너 본인의 손글씨에서 출발한 서체로, 손글씨가 가진 자연스러운 획의 흐름 및 감정의 떨림과 여백의 호흡을 최대한 보존하면서도 드라마 <연인>이 지닌 사극적 분위기와 시대적 감성을 반영하도록 재구성한 서체이다.',5,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('65af2706-4bd9-5cb5-ae02-b3751c77dc08','b334dae2-42e8-5f86-a27d-32291c401bec','google_drive','1-A8YqeNdABwNumd3BB3M8YcrhS45b4m7','연인체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('b9f7fab3-3984-57fe-a46c-41c30d5f79ff','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','거미체','Spider-Man 3에서 출발해 거미를 모티프로 제작했다. 가느다란 곡선을 중심으로, 글자의 전반적인 형태에 거미의 머리와 몸통 형상을 담고 받침을 길게 늘여 강조했다. 또한 영화 속 베놈의 점액질 같은 질감을 반영해, 각 글자가 서로 유기적으로 연결되도록 표현했다.',6,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('30a00a44-0ce2-5dde-a996-55c0faf85c45','b9f7fab3-3984-57fe-a46c-41c30d5f79ff','google_drive','1PTCrGYOIWm3gJfpOWUWAsVKNiMMVYVXU','거미체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('cf172f4d-2f40-53ca-a7e0-526014f1e126','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','쿨쿨쿨...체','아이 글꼴보기집은 드라마 Brooklyn Nine-Nine의 유머러스한 분위기를 서체로 풀어낸 결과물이다. 기울기 있는 탈네모꼴 구조를 통해 장난기와 리듬감을 담아내고, 사건 파일처럼 구성해 형사 드라마 특유의 재치와 속도감을 시각화했다.',7,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('f133ff11-a98b-5284-addc-1347fba122b6','cf172f4d-2f40-53ca-a7e0-526014f1e126','google_drive','1wC4uu8ZLCCwU3gLpAoyoEteXIwFSvOv_','쿨쿨쿨...체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('b81c8832-b21f-5461-a00a-5c64349d1850','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','안부 글씨','영화 <러브레터>의 정서에서 출발한 안부 글씨는 일본어 손글씨의 리듬과 여백을 한글로 재해석한 글꼴이다. 자유로운 흐름 속에는 섬세한 기울기와 반복이 만든 견고한 규칙성이 숨어 있다. 안부 글씨가 전하는 정제된 자유로움을 만나보길 바란다.',8,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('e4a01c2a-b7ee-57da-a711-ef6dc0a7e0a9','b81c8832-b21f-5461-a00a-5c64349d1850','google_drive','1tUmGAvzJY2os7ue8Kjr8PjFyPKh06wdC','안부 글씨',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('bb69a96d-71d7-50f6-a9e2-9c9d761decc2','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','위플래쉬','영화가 보여주는 완벽 강박의 구조를 글자로 번역한 작업이다. 자유가 아닌 통제로 기능하는 음악처럼, 정형화된 고딕 구조와 날카로운 꺾임을 통해 정확성만을 요구받는 긴장과 압박의 리듬을 획의 두께와 간격으로 시각화했다.',9,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('abbfd889-9a05-5ce3-a6fe-7bbf8fe36b24','bb69a96d-71d7-50f6-a9e2-9c9d761decc2','google_drive','1S3C3-IkPa9vD4pi5pY7-TsJJWNQqD4l8','위플래쉬',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('25b3efec-643c-5403-ae89-81d83af30bfe','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','원령체','''원령체 글꼴보기집’은 영화 원령공주를 보고 그린 글꼴과 레터링을 소개하는 책이다. 원령공주 레터링은 여자 주인공 ‘산’의 목걸이 장식을 바탕으로, 자연적 흐름이 느껴지도록 그렸다. 원령체는 새싹이나 나뭇가지가 뻗어나가는 모습을 떠올리며 제작한 민부리 계열 서체이다.',10,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('9bbe72f9-0c55-5144-a198-7eda95adde83','25b3efec-643c-5403-ae89-81d83af30bfe','google_drive','1FMt_xGX_7bMPpnIpXqxJmSqs-Fstaonk','원령체',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('cf686630-d9ee-5c2c-a3f8-528f61744d88','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','노조미체','애니메이션 <소니 보이>의 주인공 노조미의 이름을 따온 서체이다. 프레임에는 애니메이션 속의 대사들을 임의로 나열하고, 내지는 글꼴보기집으로 구성했다. 병렬적으로 놓인 세계관을 판형에 반영하고자 했다.',11,true) on conflict(id) do nothing;
