insert into public.works(id,project_id,title,description,sort_order,published) values('9d89e5de-d4cb-58fd-a9e7-3fb77329f066','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','건반체','영화 〈소울〉에서 영감을 받은, 길쭉한 피아노 건반을 닮은 서체이다.',12,true) on conflict(id) do nothing;
