insert into public.works(id,project_id,title,description,sort_order,published) values('876e2835-64f0-5463-a587-c20bec666755','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','홀리체','''홀리체''는 자유롭고 화려한 삶을 동경하는 「티파니에서 아침을」의 여주인공 홀리 골라이틀리에게서 영감을 받아 탄생한 제목용 글꼴이다. 긴 파이프 담배를 물고 서있는 오드리 헵번의 모습을 모티브로 장체 형태의 장식적인 글자들을 그려냈다.',13,true) on conflict(id) do nothing;
