insert into public.works(id,project_id,title,description,sort_order,published) values('a86bb178-fdb9-5ddb-ab7f-6db46d19ba60','3edc4b4f-5ef7-5396-aa64-2a8abba8e861','영군체','영화 〈싸이보그지만 괜찮아〉의 주인공인 영군을 모티브로 제작한 서체. 영군은 스스로를 싸이보그라 칭하지만, 사실 누구보다 따뜻하고, 사랑스럽고, 인간적이다. 휴머니스트 산스를 기반으로 하되, 곡선 획을 직선으로 처리하여 싸이보그 속 인간적인 영군의 모습을 표현했다.',14,true) on conflict(id) do nothing;
