insert into public.projects(id,legacy_id,generation_id,name,description,duration_text,project_type,sort_order,published) values('261a23ef-6dfc-571f-a087-9061f58efbff','13-5',13,'한글 연력','다가올 한 해의 다짐과 소망을 되새기며 한글 레터링 달력을 제작했습니다. 서로 다른 감각과 리듬으로 배열된 365개의 날들을 따라가 보세요.','2026.01.06. - 2026.02.17.','레터링',4,true) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('a44fdb60-a2d4-5639-a5c7-9d8f0c09b906','261a23ef-6dfc-571f-a087-9061f58efbff','무시무종; 12연기력','12연기의 구조를 시간 위에 배치한 연중 달력이다. 12연기는 인간이 왜 고통을 겪고 윤회하는지를 12단계의 인과관계로 설명하는 불교의 가르침이다. 시작과 끝이 없는 세계관인 무시무종을 바탕으로 달력이라는 시간 단위에 대응시켜 삶과 윤회의 흐름을 시각화한다.',0,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('de2f3d1f-88d8-51f0-ac88-8be6bba8d704','a44fdb60-a2d4-5639-a5c7-9d8f0c09b906','google_drive','18mvwizU8DywOUgeddGPM2qzQJ23FPq_I','무시무종; 12연기력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('b98c7c64-21fa-5731-a329-562a85ac8ad2','261a23ef-6dfc-571f-a087-9061f58efbff','2026 한붓 그리기','꽃에서의 첫 활동으로 그렸던 ‘꽃’ 레터링에서 출발한 한글 연력이다. 한 획으로 이어 그린 유연한 글자들이 모인 달력이다.',1,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('c25cf611-65f0-5bb3-aeff-379abcb9789e','b98c7c64-21fa-5731-a329-562a85ac8ad2','google_drive','1YXF5rZJm6etE_Dq-UlyAe8E6nkiJ2Iro','2026 한붓 그리기',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('32122ddb-ab7a-5fe8-a050-8ccdf11bf9bd','261a23ef-6dfc-571f-a087-9061f58efbff','2026 Now Playing','음원 사이트가 매년 제공하는 음악 연말결산 서비스에서 아이디어를 얻어 월별 K-pop 달력을 구성하였다. 월별로 가장 많이 들었던 K-pop 곡 속의 가장 좋아하는 한글 가사를 레터링으로 표현하여 이 노래들을 듣던 기억과 한글 가사의 아름다움을 달력에 담고자 하였다.',2,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('9d392e5c-436a-52e8-a541-3369f2144d79','32122ddb-ab7a-5fe8-a050-8ccdf11bf9bd','google_drive','1pSd1DQEHjeQ3KduW6s7KmVOCid2wVMY9','2026 Now Playing',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('62008a7c-44fe-568b-a9e1-d67f94d6db59','261a23ef-6dfc-571f-a087-9061f58efbff','레드데이즈','바쁜 현대인들을 위한 2026년의 쉬는 날만 모은 달력이다.',3,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('c770bcdb-a61a-5370-a0da-7cadc51592d5','62008a7c-44fe-568b-a9e1-d67f94d6db59','google_drive','1C5FpM4w8qTfKTCAMUa0o7FXz58su_6XW','레드데이즈',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('81c6dbcf-3afe-585b-ae2b-4865182a4721','261a23ef-6dfc-571f-a087-9061f58efbff','산타의 디데이','산타는 12월에만 존재할까? 보이지 않는 계절 속에서도 그는 천천히 크리스마스를 준비하고 있을지 모른다. 12월의 산타가 아닌, 1년의 산타. 기다림의 시간을 한글 레터링으로 풀어낸다.',4,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('e072127d-4359-59ce-abc1-fab8ec28d1af','81c6dbcf-3afe-585b-ae2b-4865182a4721','google_drive','1AY8Gn6ZhZe39yUs6-hAsh07fCN1yJRKE','산타의 디데이',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('7209711e-0f30-5793-adc5-45ca8870f66d','261a23ef-6dfc-571f-a087-9061f58efbff','트릴 메모 연력','기존 영문 서체인 “Trille” 서체를 기반으로 제작한 한글 레터링 메모 연력이다',5,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('624b5036-63ef-5493-aa58-cc6c28b5a0a7','7209711e-0f30-5793-adc5-45ca8870f66d','google_drive','1olrWdfVQUOy3tGmXauSXHkgdioAKmuGI','트릴 메모 연력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('fb8614c9-15e3-5866-ae9e-c8ffed4731ed','261a23ef-6dfc-571f-a087-9061f58efbff','일기장 달력','어린 아이가 세상을 바라보는 마음으로 달력을 만들었다. 또박또박하지 않은 유아어로 하루를 적어 내려가며, 한 장 한 장을 작은 일기장처럼 구성했다. 각 달마다 있는 특별한 이벤트를 소주제로 삼아 그날의 설렘과 궁금함을 짧은 글로 담았다. 귀여운 글자와 아기자기한 그림을 더해, 한 해가 순수한 시선으로 기록되도록 표현했다.',6,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('fadc5955-1120-595e-ad1d-058651f60e17','fb8614c9-15e3-5866-ae9e-c8ffed4731ed','google_drive','16j8IEhf0NH3mpcLVrvNAKkoesHgSqqE7','일기장 달력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('95a44b37-7511-59e9-a572-b3abec2bdb2f','261a23ef-6dfc-571f-a087-9061f58efbff','십이간지','십이간지는 시간을 단순한 숫자가 아닌 상징과 이야기로 풀어내는 전통적 방식이다. 열두 동물이 지닌 성격과 이미지를 달의 흐름에 겹쳐 배치함으로써, 한 해를 보다 감각적이고 서사적으로 경험할 수 있는 달력을 만들고자 했다.',7,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('ca0d9dfe-5a0a-5e74-ac62-e3f383d0ca10','95a44b37-7511-59e9-a572-b3abec2bdb2f','google_drive','1-W62bkZS4eUXgK1-PKjpgOk0A6Szzv1t','십이간지',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('f7f17206-e42e-5c43-a4b4-6440e8f61c9e','261a23ef-6dfc-571f-a087-9061f58efbff','이달의 멜로디','‘이달의 멜로디’는 매일의 기분을 음의 높낮이로 기록하는 달력이다. 즐거웠던 날엔 높은 음을, 아쉬웠던 날엔 낮은 음을 원형 스티커로 표현해보자. 한 달이 지나면 당신만의 짧은 악보가 완성된다.',8,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('75585cf2-ace0-5dab-a768-a8ebafc92311','f7f17206-e42e-5c43-a4b4-6440e8f61c9e','google_drive','1E4UwNINW5JJa34qJmWmjgg1eUVWevVpO','이달의 멜로디',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('df62eec4-bc4f-585b-a146-055d878bf1ff','261a23ef-6dfc-571f-a087-9061f58efbff','점으로 기록','픽셀 도트로 구성된 한글 연력을 통해 시간을 점의 개수로 표기한 작업이다. 월마다 앞에 더해진 점들은 흐르는 시간의 누적을 상징하며,  글자 구조 위에 반복되는 점은 규칙과 리듬을 드러낸다.',9,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('840e5647-3547-5f3b-ada1-1c4c598b3572','df62eec4-bc4f-585b-a146-055d878bf1ff','google_drive','1FGR58tC7X26tbt9twAnCeOlJ3QySZGN0','점으로 기록',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('440c0f91-755b-50c5-a023-04463d0c0064','261a23ef-6dfc-571f-a087-9061f58efbff','모아핌 연력','모아핌 연력은 열두 달이 모여 하나의 꽃표 형태를 이룬다. 꽃표(별표)는 중요한 부분을 표시하는 기호로, 이 작업에서는 한 해를 가리킨다. 각각의 달력 속 무늬는 단순해 보이지만 지나간 시간들이 모여 하나의 꽃표를 완성하고, 뜻있는 한 해로 남는다는 의미를 담고 있다.',10,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('8c6adb19-7e1e-553d-a963-f638e92f1a08','440c0f91-755b-50c5-a023-04463d0c0064','google_drive','1MVGLHMKg0kD2MGnIyJ0Fum_k8RjPg5L-','모아핌 연력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('93716e2a-1d53-52ed-a5df-d411e671fc90','261a23ef-6dfc-571f-a087-9061f58efbff','세계 동물의 날 달력','플레잉 카드의 형식을 빌려 앞면에는 달력을, 윗면에는 각 달에 해당되는 동물의 일러스트를 넣었다. 달은 일반적으로 쓰이는 숫자 대신 한글 레터링으로 표기했다. 달력 면에서 세계 동물의 날을 확인해 볼 수 있다.',11,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('cc8a013d-f420-5d02-a089-a6afc3fd7e2f','93716e2a-1d53-52ed-a5df-d411e671fc90','google_drive','1jeVcTjCRkCpYLaiQRgF7Ab9tqhLxT1JA','세계 동물의 날 달력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('dd2b9720-61cf-5abf-a80e-f8a84fb5dd82','261a23ef-6dfc-571f-a087-9061f58efbff','이공이육','자소의 조합 구조를 강조한 레터링 달력이다.',12,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('2cb72217-5829-5b37-ab8b-d9d0917c059b','dd2b9720-61cf-5abf-a80e-f8a84fb5dd82','google_drive','1wwvE66SH6NJG2R19Hh2IDX1JblFvQsiy','이공이육',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('0a292024-2216-543d-aa14-710eca302ac7','261a23ef-6dfc-571f-a087-9061f58efbff','별자리 달력','별자리 달력은 1부터 12까지의 숫자가 아닌 별자리를 기준으로 달을 나누는 달력이다. 다양한 별자리를 아기자기하고 귀여운 일러스트로 표현했다.',13,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('7d766fb8-9b64-5188-a538-0e08f78f865d','0a292024-2216-543d-aa14-710eca302ac7','google_drive','1tl4gF-dzMlQuyokXs3mYv0RG98yvMqfg','별자리 달력',0) on conflict(id) do nothing;
insert into public.works(id,project_id,title,description,sort_order,published) values('1e146535-06cf-59bd-af3f-6d86234d98d1','261a23ef-6dfc-571f-a087-9061f58efbff','문장 부호 달력','한 달에 하나씩, 열두 개의 문장 부호를 소개한다. 각기 다른 서체 속에서 드러나는 문장 부호의 형태적 특징을 관찰하고, 이를 레터링으로 재해석했다.',14,true) on conflict(id) do nothing;
insert into public.work_images(id,work_id,provider,path,alt_text,sort_order) values('16027ae4-7fc6-5d8c-a5d4-4050bcfcb652','1e146535-06cf-59bd-af3f-6d86234d98d1','google_drive','1o2DmvQ5RInSym61AoeVbv3DkaZoMpiah','문장 부호 달력',0) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('177aa795-3c9c-5087-adeb-c4a030114583','flower-night-1','꽃밤 하루','[]'::jsonb,'2019.02.23.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_1.jpg',0,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('d4a32a5b-41e2-558a-a693-caf596a529c4','flower-night-2','꽃밤 둘, 가드닝 파티','[]'::jsonb,'2020.02.09. - 2020.02.10.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_2.jpg',1,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('52f86a9c-8478-5ad1-a942-87868aeec6b3','flower-night-3','꽃밤 셋, 네이밍 파티','["이름 글자에 담긴 의미와 존재에 대한 이야기입니다. 태어나서부터 함께하는 가장 친숙한 글자이지만 깊게 들여다 볼 기회가 없는 이름의 다양한 해석을 선보입니다. 또한, 단 세 글자가 표현하는 한 사람은 어떤 모습일지 나타냅니다."]'::jsonb,'2021.03.02. - 2021.03.06.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_3.jpg',2,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('b742dad7-6fc9-518e-a8f1-b8db35695972','flower-night-4','꽃밤 넷, Ex Libris 꽃','["⟨Ex Libris 꽃⟩에서 꽃은, 당신이 염원하는 모습의 2022년을 보내길 바라는 마음을 담아 세 권의 책과 칵테일을 레터링으로서 전달했습니다. 전시 내의 모든 책은 누구나 어렸을 적에 접해봤을 법한 이야기인 동시에 이제는 어른이 된 우리들에게 아직까지 교훈을 주곤 하는 동화입니다. ⟨Ex Libris 꽃⟩은 관람객이 2022년을 살아가는 데에 도움이 될 만한 가치를 마음에 새길 수 있도록 돕습니다."]'::jsonb,'2022.02.25. - 2022.02.27.','성북구 369 예술터','local','../assets/img/exhib/exhib_4.jpg',3,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('0a99d850-315a-55f6-a853-562071ccdca7','flower-night-5','꽃밤 다섯, 꽃잔치, 글자가옥에서 맞이하는 순년','["반갑습니다. 2023년, 꽃이 올겨울 추위를 이겨내고 순년을 맞이하며 〈꽃잔치〉를 베풀게 되었습니다. 이번 정기전에서의 꽃은, 당신이 계묘년(癸卯年)을 무사히 살아가는 데에 도움이 될 만한 가치를 글자에 담아 빚었습니다. 각 전시 공간은 잔치를 베푸는 공간이자 하나의 글자가옥이며, 중심에 있는 사랑채는 한국적인 정서를 꽃의 새로운 해석으로 보여줍니다. 가옥의 다른 방들 또한 글자에 대한 새로운 시선을 담았으니 편히 즐겨주시길 바라겠습니다. 글자로써 건네는 꽃의 기원과 함께 무사태평한 2023년을 보내시기를 소망합니다."]'::jsonb,'2023.02.28. - 2023.03.05.','wrm space(서울 마포구 잔다리로3안길46 L층)','local','../assets/img/exhib/exhib_5.jpg',4,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('31a9131b-7ece-5723-aa28-eb505f0d24ae','flower-night-6','꽃밤 여섯, 꽃꽂이','["책장에 책을 꽂아 정렬하는 행위는 꽃꽂이와 닮아있습니다. 각 책장은 색깔, 형태, 장르를 헤아려 다양하고 조화롭게 구성되곤 합니다. 꽃밤 여섯 《꽃꽂이flower arrangement》는 꽃꽂이를 하듯 정성스레 마련한 작은 책방입니다.","문학에서 파생된 서체와 같이 책을 모티프로 하는 타이포그래피는 물론, 독서에 곁들이는 꽃말 책갈피가 여러분을 맞이합니다. 이외에도 꽃의 해석이 담긴 영화 속 문장들, 한글 학습 브랜드를 녹여내어 글자의 시각적 아름다움을 이야기합니다.","글자를 배열하고 조정하는 타이포그래피 또한 꽃꽂이와 닮아 있습니다. 그 기능적 면모에서 시각적 매력까지, 한글을 보는 즐거움을 함께하길 바랍니다."]'::jsonb,'2024.03.11. - 2024.03.16.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_6.jpeg',5,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('4af03571-2068-5b98-a7bd-af2b4379f5e9','flower-night-7','꽃밤 일곱, 꽃누르미','["꽃누르미, 압화는 식물의 표본을 만드는 과정에서 비롯되었습니다. 수분을 제거한 꽃을 누르고, 오랜 시간을 들여 말리는 꽃누르미는 순간을 오래도록 보존하려는 바람을 담고 있습니다. 꽃의 시간을 붙잡듯, 종이에 활자를 눌러 만든 찰나의 표본을 선보입니다.","일곱 번째 꽃밤, 꽃누르미는 영원한 순간을 담은 표본실입니다.","이곳의 표본은 일상 속 가장 아름다운 순간을 골라 평면의 형태로 보존한 기록입니다. 소리와 움직임, 특정한 날, 어떠한 대상을 순간의 형태로 포착하여 당신께 전합니다. 악보, 배리어블 레터링, 엽서, 서체의 다양한 형태를 지닌 표본들을 만나보세요.","곱게 골라 글자의 형태로 눌러낸 꽃의 시간을 당신의 방식으로 붙잡아주시길 바라겠습니다."]'::jsonb,'2025.03.11. - 2025.03.15.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_7.jpeg',6,true) on conflict(id) do nothing;
insert into public.exhibitions(id,legacy_id,title,description,duration_text,place,cover_provider,cover_path,sort_order,published) values('4c514e05-e1dd-560c-a57f-a9b4d4b5b4d0','flower-night-8','꽃밤 여덟, 꽃표 Shift+8','["키보드에서 Shift와 8을 함께 누르면 꽃표(*)가 입력된다.","꽃표는 문장 안에서 다양한 쓰임을 가진다. 특정 단어를 강조하거나 설명을 덧붙이는 표식이 되며, 잘못된 표현을 정정하거나 일부를 가리는 용도로 사용된다. 늘 본문 곁에 놓여 의미를 보조하지만, 때로는 맥락에 개입하며 문장의 흐름을 바꾸기도 한다.","단어의 어깨 위, 문장 곳곳에 보이는 아주 작은 표식. 우리는 그곳을 자세히 들여다 본 적이 있을까. 작은 크기 안에서 점과 선이 관계를 이루고 있는 꽃표는 그자체로 완결된 조형성과 균형을 드러낸다. 여덟 번째 꽃밤, 〈꽃표 (Shift+8)〉는 이 기호를 전면에 내세우며 꽃표처럼 늘 곁에 있었지만 주목받지 못했던 한글 타이포그래피의 형태 그 자체를 조명한다.","한글 타이포그래피는 오랫동안 언어의 뒤편에서 기능해왔다. 의미를 보조하던 요소가 하나의 조형으로서 전면에 서게 될 때 우리는 어떤 아름다움을 발견할 수 있을까. 우리는 오늘 이곳에서 한글 타이포그래피의 다양한 가능성을 마주하게 된다. 지금까지 익숙하게 읽어오던 방식에서 잠시 벗어나, 글자가 스스로를 드러내는 순간을 함께 따라가보자."]'::jsonb,'2026.2.28, 2026.3.3. - 2026.3.5.','이화여자대학교 ECC B3 대산갤러리','local','../assets/img/exhib/exhib_8.jpeg',7,true) on conflict(id) do nothing;
