insert into public.notices(id,title,date_text,contents,sort_order,published) values('4b7dae26-cdb1-5c98-a72b-dbc0357901d5','꽃 13.0 신입부원 모집','2025.3.10.','["이화여자대학교 한글 타이포그래피 소모임 <꽃>은 김춘수 ''꽃''의 한 구절인 ''내가 그의 이름을 불러 주었을 때 그는 나에게 로 와서 꽃이 되었다''에서 이름을 빌려왔습니다. 꽃은 의미 있게 다가오는 요소를 디자이너의 그래픽 작업을 통해 새로운 가치로 만들어내고, 실험하고 있습니다. 또한 대학생 중심의 디자인 운동으로서 대중에게 가까이 다가가 다양한 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다.","<br>이번 12.0기에서는 한글의 조형성을 탐구하고 타이포그래피 공모전에 도전하는 등 교내 안팎으로 다양한 활동을 전개했습니다.","<br>—","<br>🌷 지원 마감 : 3월 16일 (일) 23:59","🌷 모집 대상 : 이화여자대학교 디자인학부 학생 중 매주 1회 정기 모임이 가능한 2~3학년","🌷 지원 내용 : 타이포그래피와 그래픽디자인 위주의 포트폴리오 파일 첨부, 메일 본문에 이름 •과•학년• 이수학기 •전화번호 •500자 이내의 지원동기 표기, 파일 용량 20MB 이하","🌷 메일 : <a href=\"mailto:come.as.flower@gamil.com\">come.as.flower@gamil.com</a>","(*2025년 기준 2년 활동 참여 필수)","(*1년마다 진행하는 꽃의 정기 행사인 ''꽃밤'' 2번 필수)","(기존 모임 시간은 화요일 7시, 모임 시간 추후 변경될 수 있습니다.)","<br>—","<br>일정","🌷 1차 결과 발표 : 3/19(수) 개인 문자 예정","🌷 1차 합격자 면접 : 3/22(토)","🌷 최종 결과 발표 : 3/23(일) 개인 문자 예정"]'::jsonb,2,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('5f256ec9-3082-5753-a654-f28a71197202','네 번째 세미나, 박신우 디자이너','2025.3.4.','["일곱 번째 꽃밤, 《꽃누르미pressed flower》가 ECC 대산갤러리에서 3월 11일 화요일부터 15일 토요일까지 진행됩니다. 전시의 마지막날, 3월 15일 토요일 11시에 오픈 세미나를 열게 되었습니다.","<br>이번 세미나는 꽃의 선배님이시자 그래픽 디자인 스튜디오 페이퍼프레스를 운영하고 계신 박신우 교수님(<a href=\"https://www.instagram.com/paper_press/\">@paper_press</a>)을 연사님으로 모셨습니다. 연사님의 강연과 Q&A 시간으로 구성될 예정입니다.","<br>선착순으로 꽃 프로필 링크의 구글 폼으로 신청을 받고 있습니다. 공간 상의 이유로 인원 제한이 있어 사전 신청한 디자인학부 학생에 한해 선착순으로 진행 됩니다.","<br>—","<br>🌷 일시: 2025.3.15.(토) 11:00","🌷 여는 곳: 이화여자대학교 ECC B3 대산갤러리","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃","🌷 신청 폼 주소: 마감되었습니다."]'::jsonb,3,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('a4bddd32-d5a5-5add-a810-db2e8deb6ae6','꽃밤 일곱, 《꽃누르미pressed flower》','2025.3.1.','["꽃누르미, 압화는 식물의 표본을 만드는 과정에서 비롯되었습니다. 수분을 제거한 꽃을 누르고, 오랜 시간을 들여 말리는 꽃누르미는 순간을 오래도록 보존하려는 바람을 담고 있습니다. 꽃의 시간을 붙잡듯, 종이에 활자를 눌러 만든 찰나의 표본을 선보입니다.","<br>일곱 번째 꽃밤, 꽃누르미는 영원한 순간을 담은 표본실입니다.","<br>이곳의 표본은 일상 속 가장 아름다운 순간을 골라 평면의 형태로 보존한 기록입니다. 소리와 움직임, 특정한 날, 어떠한 대상을 순간의 형태로 포착하여 당신께 전합니다. 악보, 배리어블 레터링, 엽서, 서체의 다양한 형태를 지닌 표본들을 만나보세요.","<br>곱게 골라 글자의 형태로 눌러낸 꽃의 시간을 당신의 방식으로 붙잡아주시길 바라겠습니다.","<br>—","<br>🌷 여는 기간: 2025.3.11.(화) – 3.15.(토)","🌷 여는 시간: 11:00 – 19:00, 토요일 16:00 마감","🌷 여는 곳: 이화여자대학교 ECC B3 대산갤러리","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃"]'::jsonb,4,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('c0e53186-d3f3-5b85-a2b6-21b0cf382e16','꽃 12.0 신입부원 모집','2024.3.9.','["이화여자대학교 한글 타이포그래피 소모임 〈꽃〉은 김춘수 ‘꽃’의 한 구절인 ‘내가 그의 이름을 불러 주었을 때 그는 나에게로 와서 꽃이 되었다’에서 이름을 빌려왔습니다. 꽃은 의미 있게 다가오는 요소를 디자이너의 그래픽 작업을 통해 새로운 가치로 만들어내고, 실험하고 있습니다. 또한 대학생 중심의 디자인 운동으로서 대중에게 가까이 다가가 다양한 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다.","<br>꽃은 의미 있게 다가오는 요소를 새로운 가치로 만들어내고, 실험하고 있습니다. 나아가 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다. 이번 11.0기에서는 타이포그래피 스터디 활동과 함께, 레터링 및 다양한 물성의 한글 연구를 진행하였습니다.","<br>—","<br>🌷 지원 마감 : 3월 20일 (수) 23:59","🌷 모집 대상 : 이화여자대학교 디자인학부 학생 중 매주 1회 정기 모임이 가능한 2~3학년","🌷 지원 내용 : 타이포그래피와 그래픽디자인 위주의 포트폴리오 파일 첨부, 메일 본문에 이름 · 과 · 학년 · 이수학기 · 전화번호 · 500자 이내의 지원동기 표기","🌷 메일 : <a href=\"mailto:come.as.flower@gamil.com\">come.as.flower@gamil.com</a>","<br>—","<br>일정","🌷 1차 결과 발표 : 3/21(목) 개인 문자 예정","🌷 1차 합격자 면접 : 3/23(토)","🌷 최종 결과 발표 : 3/24(일) 개인 문자 예정"]'::jsonb,5,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('50ffa4ef-814e-5f2b-a37e-c1db918b53c0','세 번째 세미나, 조소희 디자이너','2024.3.8.','["전시 마지막 날인 3월 16일 토요일 오후 4시, 오픈 세미나가 열립니다!","<br>세미나에는 꽃의 선배님 조소희 그래픽 디자이너(<a href=\"https://www.instagram.com/wrkjoewrk/\">@wrkjoewrk</a>)님을 연사님으로 모셨습니다. 세미나는 연사님의 강연과 Q&A 시간으로 구성될 예정입니다.","<br>본 세미나는 선착순으로 꽃 프로필 링크의 구글 폼을 작성한 디자인학부 학생에 한해 진행됩니다. (인원 제한이 있어 조기 마감될 수 있습니다.)","<br>—","<br>🌷 일시: 2024년 3월 16일 (토) 오후 4시","🌷 장소: 이화여자대학교 ECC 대산갤러리","🌷 신청 폼 주소: 마감되었습니다. 감사합니다!"]'::jsonb,6,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('de1787ad-68e5-5972-a8a8-09deaf462da6','꽃밤 여섯, 《꽃꽂이flower arrangement》','2024.3.7.','["책장에 책을 꽂아 정렬하는 행위는 꽃꽂이와 닮아있습니다. 각 책장은 색깔, 형태, 장르를 헤아려 다양하고 조화롭게 구성되곤 합니다. 꽃밤 여섯 《꽃꽂이flower arrangement》는 꽃꽂이를 하듯 정성스레 마련한 작은 책방입니다.","<br>문학에서 파생된 서체와 같이 책을 모티프로 하는 타이포그래피는 물론, 독서에 곁들이는 꽃말 책갈피가 여러분을 맞이합니다. 이외에도 꽃의 해석이 담긴 영화 속 문장들, 한글 학습 브랜드를 녹여내어 글자의 시각적 아름다움을 이야기합니다.","<br>글자를 배열하고 조정하는 타이포그래피 또한 꽃꽂이와 닮아 있습니다. 그 기능적 면모에서 시각적 매력까지, 한글을 보는 즐거움을 함께하길 바랍니다.","<br>—","<br>🌷 전시 기간: 2024년 3월 11일 (월) – 3월 16일 (토)","🌷 관람시간: 11:00 – 19:00 (11일 월요일은 14:00 오픈)","🌷 장소: 이화여자대학교 ECC B3 대산갤러리","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃","<br>","* 3월 16일 (토) 의 경우 내부 행사 진행으로 15시 30분에 일반 관람이 마감된다는 점 유의부탁드리겠습니다."]'::jsonb,7,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('0cfe479d-94ed-5bf3-a98a-e37edc949e0a','꽃 11.0 신입부원 모집','2023.3.8.','["이화여자대학교 한글 타이포그래피 소모임 〈꽃〉은 김춘수 ‘꽃’의 한 구절인 ‘내가 그의 이름을 불러 주었을 때 그는 나에게로 와서 꽃이 되었다’에서 이름을 빌려왔습니다. 꽃은 의미 있게 다가오는 요소를 디자이너의 그래픽 작업을 통해 새로운 가치로 만들어내고, 실험하고 있습니다. 또한 대학생 중심의 디자인 운동으로서 대중에게 가까이 다가가 다양한 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다.","<br>꽃은 의미 있게 다가오는 요소를 새로운 가치로 만들어내고, 실험하고 있습니다. 나아가 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다. 이번 11.0기에서는 타이포그래피 스터디 활동과 함께, 레터링 및 다양한 물성의 한글 연구를 진행하였습니다.","<br>—","<br>🌷 지원 마감 : 3월 14일(화) 자정 24:00","🌷 모집 대상 : 이화여자대학교 디자인학부 학생 중 매주 1회 정기 모임이 가능한 2~3학년","🌷 지원 내용 : 타이포그래피와 그래픽디자인 위주의 포트폴리오 파일 첨부, 메일 본문에 이름 · 과 · 학년 · 이수학기 · 전화번호 · 500자 이내의 지원동기 표기","🌷 메일 : <a href=\"mailto:come.as.flower@gamil.com\">come.as.flower@gamil.com</a>","<br>—","<br>일정","🌷 1차 결과 발표 : 3/16(목) 개인 문자 예정","🌷 1차 합격자 면접 : 3/18(토)","🌷 최종 결과 발표 : 3/19(일) 개인 문자 예정"]'::jsonb,8,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('ac77f395-6231-5a45-a3d4-6e1490986534','꽃밤 다섯, 《꽃잔치, 글자가옥에서 맞이하는 순년》','2023.2.21.','["<br>반갑습니다. 2023년, 꽃이 올겨울 추위를 이겨내고 순년을 맞이하며 〈꽃잔치〉를 베풀게 되었습니다. 이번 정기전에서의 꽃은, 당신이 계묘년(癸卯年)을 무사히 살아가는 데에 도움이 될 만한 가치를 글자에 담아 빚었습니다. 각 전시 공간은 잔치를 베푸는 공간이자 하나의 글자가옥이며, 중심에 있는 사랑채는 한국적인 정서를 꽃의 새로운 해석으로 보여줍니다. 가옥의 다른 방들 또한 글자에 대한 새로운 시선을 담았으니 편히 즐겨주시길 바라겠습니다. 글자로써 건네는 꽃의 기원과 함께 무사태평한 2023년을 보내시기를 소망합니다.","<br>—","<br>🌷 전시기간: 2023.2.28.(화)–3.5.(일)","🌷 관람시간: 11:00–19:00","🌷 장소: wrm space(서울 마포구 잔다리로3안길46 L층)","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃"]'::jsonb,9,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('f4c17770-10b3-5551-a430-baea88b30466','두 번째 세미나, 이주희 디자이너','2022.7.1.','["<br>6월 28일, 꽃의 2022년도 오픈 세미나가 무사히 마무리 되었습니다! 세미나에는 조예대 선배님이자 꽃의 선배님 🌺 이주희(Nohtype, 서체 디자이너) 디자이너🌺를 연사님으로 모셨습니다. 세미나는 연사님의 강연과 Q&A 시간으로 구성되었습니다.","<br>—","<br>🌷 일시: 2022년 6월 28일(화) 오후 7시","🌷 장소: 온라인 구글밋을 통해 진행","🌷 본 세미나는 신청자에 한해 진행되었습니다."]'::jsonb,10,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('d279a472-ae18-5c40-a176-22ce1d968fe5','첫 번째 세미나, 이예연 디자이너','2021.2.27.','["<br>2월 27일, 꽃의 첫 온라인 세미나가 열립니다! 세미나에는 조예대 선배님이자 꽃의 선배님 🌺이예연(이응셋 스튜디오, FDSC 운영진) 디자이너🌺를 연사님으로 모셨습니다. 세미나는 연사님의 강연과 Q&A 시간으로 구성될 예정입니다.","<br>—","<br>🌷 일시: 2021년 2월 27일(토) 오후 2시","🌷 장소: 온라인 구글밋을 통해 진행","🌷 본 세미나는 신청자에 한해 진행되었습니다."]'::jsonb,11,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('329f284f-8536-5268-a6e9-c9c7ee15389f','20번째 한울전, 《아카이브,2000》','2020.10.9.','["20번째 한울전 ‘아카이브,2000’에 꽃이 참여했습니다! 꽃은 ‘2000년대 스포츠그래피’를 주제로 각자 2000년대에 개최된 하계 올림픽을 하나씩 선정하여 해당 올림픽의 아이덴티티를 드러내는 타이틀과 슬로건의 문구를 담은 포스터를 제작하였습니다."]'::jsonb,12,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('c9020735-2b0f-5da3-acea-c689eaf99e1d','꽃밤 둘, 《가드닝 파티gradening party》','2020.2.2.','["<br>하나의 꽃을 정해 레터링과 그래픽, 오브제로 풀어냅니다.","<br>—","<br>🌷 전시기간: 2020.2.9.–2.10.","🌷 관람시간: 11:00–20:00","🌷 장소: 이화여자대학교 ECC B3 대산갤러리","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃"]'::jsonb,13,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('ffd1d27c-6545-577f-a054-5b272889a919','꽃 8.0 지원 관련 변경사항 안내','2020.1.19.','["많은 분들이 학년 관련하여 문의사항 주셔서 모집 관련 사항을 다소 변경하기로 하였습니다.","<br>—","<br>*4학년 지원 가능","타이포그래피 관련 활동(레터링, 편집디자인 등)에 능숙하여, 2~3학년 신입생들을 작업적 측면에서 리드 가능하신 분들을 소수 선발하기로 하였습니다.","<br>*모집 마감 시간 연장","지원 가능 대상이 늘어남에 따라, 모집 마감 기간을 하루 더 연장하여 20일(월) 자정으로 변경하였습니다. 이에 따라 1차 합격 통보 날짜도 21일(화)로 변경합니다.","<br>—","<br>Q. 꽃에서는 어떤 활동들을 하나요?","A. 매학기 레터링 / 그래픽 / 편집디자인 프로젝트를 진행하며, 정기전시회 \"꽃밤\"을 통해 꽃을 거쳐간 역대 선배님들과의 네트워킹의 시간 또한 가질 수 있습니다. 연합 학회 <한울>을 통한 타학교 학생들과의 교류, 국립 한글 박물관에서의 전시, 유명 디자이너님 초청 세미나 청강 등의 다양한 활동이 준비되어 있습니다.","<br>Q. 올해 2학년이 되어서 준비한 포트폴리오가 없는데 내년에 지원할래요.","A. 꽃은 학년을 고려하여 신입 모집 진행중이며, 1년 활동 가능자보다는 2년 활동가능자를 우대합니다. 형과 이미지에서 진행하였던 작업물을 가벼운 마음으로 제출해주셔도 좋습니다.","<br>—","<br>🌷 지원 마감 : 1/20(월) 자정","🌷 모집 대상 : 모집 대상 : 이화여자대학교 시각디자인학과 혹은 디자인학부 학생 중 매주 목요일 저녁에 모임이 가능한 2~3학년 + 4학년","🌷 지원 내용 : 타이포그래피와 그래픽디자인 위주의 포트폴리오 파일 첨부, 메일 본문에 이름 · 과 · 학년 · 이수학기 · 전화번호 · 500자 이내의 지원동기 표기","🌷 메일 : <a href=\"mailto:come.as.flower@gamil.com\">come.as.flower@gamil.com</a>","<br>—","<br>선발 일정","🌷 1차 결과 발표 : 1/21(화) 개인 문자 예정","🌷 1차 합격자 면접 : 1/22(수)-23(목) 저녁 중 시간 선정","🌷 최종 결과 발표 : 1/28(화) 개인 문자 예정","🌷 활동 시작일 : 1/30(목)"]'::jsonb,14,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('2384dfb9-833c-5329-ab40-806104c15189','꽃 8.0 신입부원 모집','2020.1.11.','["<br>이화여자대학교 한글 타이포그래피 소모임 〈꽃〉은 김춘수 ‘꽃’의 한 구절인 ‘내가 그의 이름을 불러 주었을 때 그는 나에게로 와서 꽃이 되었다’에서 이름을 빌려왔습니다. 꽃은 의미 있게 다가오는 요소를 디자이너의 그래픽 작업을 통해 새로운 가치로 만들어내고, 실험하고 있습니다. 또한 대학생 중심의 디자인 운동으로서 대중에게 가까이 다가가 다양한 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다.","<br>꽃은 의미 있게 다가오는 요소를 새로운 가치로 만들어내고, 실험하고 있습니다. 나아가 한글 타이포그래피의 발전 가능성을 보여주고, 한글의 우수함과 아름다움을 널리 알리고자 합니다. 이번 7.0기에서는 타이포그래피 스터디 활동과 함께, 다양한 한글 서체 개발 및 레터링을 진행하였습니다.","<br>—","<br>🌷 지원 마감 : 1월 19일(일) 자정 24:00","🌷 모집 대상 : 이화여자대학교 디자인학부 학생 중 매주 1회 정기 모임이 가능한 2~3학년","🌷 지원 내용 : 타이포그래피 위주의 간단한 pdf 파일 첨부, 메일 본문에 이름 · 과 · 학년 · 이수학기 · 전화번호 표기","🌷 메일 : <a href=\"mailto:come.as.flower@gamil.com\">come.as.flower@gamil.com</a>","<br>—","<br>선발 일정","🌷 1차 결과 발표 : 1/20(월) 개인 문자 예정","🌷 1차 합격자 면접 : 1/22(수)-23(목) 저녁 중 시간 선정","🌷 최종 결과 발표 : 1/28(화) 개인 문자 예정","🌷 활동 시작일 : 1/30(목)"]'::jsonb,15,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('ca672206-ad56-51cf-a45c-40991745218d','19번째 한울전, 《한글, 본》','2019.9.25.','["9번째 한울전 ‘한글, 본’에 꽃이 참여했습니다! 한글박물관 별관 나,다 에서 9월 24일 ~ 10월 1일까지 진행됩니다. 오픈 시간은 오전 10시에서 6시까지 입니다!! 꽃은 ‘필기구’를 주제로 각자 필기구를 선정해 그에 맞는 글씨를 레터링하고 50글자정도의 문구를 그렸습니다."]'::jsonb,16,true) on conflict(id) do nothing;
insert into public.notices(id,title,date_text,contents,sort_order,published) values('9a973243-48ad-5f92-a224-9e42adde7b06','꽃밤, 하루','2019.2.23.','["🌷 전시기간: 2019.2.23.","🌷 관람시간: 15:00–","🌷 장소: 이화여자대학교 ECC B3 대산갤러리","🌷 기획: 이화여자대학교 한글타이포그래피학회, 꽃"]'::jsonb,17,true) on conflict(id) do nothing;
